 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Arjun. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Arjun, I'm really upset. My internet has been dropping out every ten minutes and my latest bill is way higher than it should be.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you're experiencing these issues with your connection and your billing. I can certainly help you get this sorted out.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we dive into the account details, could you please provide me with your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, it is 60024878. My name is Vivek Brown and my phone number is 93101 48272.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Mr. Brown. I've accessed your account. Looking at the billing, I see the error in the charge. I guarantee you'll get a full refund on this.",
      "tags": [
        "prohibited_promise"
      ]
    },
    {
      "speaker": "agent",
      "text": "I will now raise a refund request for the wrong charge to correct your balance.",
      "tags": [
        "action:refund_request"
      ]
    },
    {
      "speaker": "customer",
      "text": "I appreciate that. But what about the network? I can't work from home if the signal keeps cutting out.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I've run a diagnostic on your line and it shows some instability. I'm going to raise a network ticket right now to have our engineers investigate the local cabinet.",
      "tags": [
        "action:technician_or_ticket"
      ]
    },
    {
      "speaker": "customer",
      "text": "That's a relief. I was worried I'd have to spend hours on the phone again. Thank you for fixing this so quickly.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "You're very welcome. Is there anything else I can assist you with today? To recap, I've requested your refund and opened a network ticket for your connection. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
